function HomelandCheckInCardHead:Refresh(groupId, memberId)
    self.groupId = groupId
    self.memberId = memberId

    ---@type CardComponent
    local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    local hasCard = cardComponent:IsHasCard(memberId)
    local cardDojo = cardComponent:GetCardByConfId(memberId)    

    ---@type CardHeadNode
    local scr = CfUtils.GetLuaScr(self.CommonSmallHeadNode, CardHeadNodeLuaPath)
    if hasCard then
        scr:FreshNode(cardDojo, false, 0, false)
    else
        scr:FreshNodeByCardVo(memberId)
    end

    scr:SetCallBack(function()
        if hasCard then
            local id = cardDojo.id
            UIModule.OpenDialog({ id = Constants.UITypeIds.CultivateMain, parameters = {playerCardId = id}}, self.excludes)
        else
            local gachaponUtils = import('Game.Gachapon.GachaponUtils')
            gachaponUtils.OpenDetail(memberId, self.excludes, {showJumpBtn = true})
        end
    end)
    KTool.SetActive(self.Mask, not hasCard)
end

return HomelandCheckInCardHead